{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 원인을 실행 계획으로 좁히는 역량을 검증한다. 신고 목록 조회의 병목을 전체 조인으로 판단한 근거 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회에 3.2초가 걸리던 상황이다.",
          "task": "조회 지연을 일으키는 병목을 실행 계획에서 식별해야 했다.",
          "action": "실행 계획에서 실제로 확인한 정보를 설명하고, 그 정보가 신고 테이블과 판매글 테이블의 전체 조인을 병목으로 지목하는 이유를 연결한다.",
          "result": "관찰한 정보로 해당 조인을 지연 원인으로 좁힐 수 있었던 이유가 드러난다. 이후 개선 성과 자체보다 원인 판단의 타당성을 확인한다."
        },
        "expectedEvidence": [
          "신고 목록 조회의 병목을 전체 조인으로 좁힌 구체적인 판단 근거",
          "실행 계획에서 본인이 실제로 확인한 정보",
          "확인한 정보와 조회 지연 사이의 인과관계"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회를 3.2초에서 0.4초로 줄이셨네요. 실행 계획에서 병목 원인을 전체 조인으로 좁힌 판단의 근거는 무엇이었나요?",
      "answerTip": "실행 계획에서 본 사실과 해석을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "전체 조인을 병목으로 좁힌 판단 근거가 구체적으로 드러난다.",
            "실행 계획에서 실제로 확인한 정보를 제시하고 그 의미를 설명한다.",
            "해당 정보가 조회 지연을 설명하는 이유를 연결해 원인 판단의 타당성을 입증한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "전체 조인을 병목으로 판단한 근거는 드러나지만 설명이 일부 추상적이다.",
            "실행 계획의 관찰 정보를 언급하지만 조회 지연과의 연결이 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "전체 조인을 병목으로 좁힌 판단 근거가 드러나지 않는다.",
            "인덱스 추가나 속도 개선 결과만 설명하고 실행 계획에서 확인한 정보를 제시하지 못한다.",
            "전체 조인이 느리다는 일반론에 머물러 해당 조회의 지연 원인을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인을 로그로 추적하고 초기 추정을 수정하는 역량을 검증한다. 알림 중복 발송의 원인을 클라이언트 문제에서 스케줄러 중복 실행으로 바꾸게 한 결정적 단서에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔고, 처음에는 클라이언트 문제로 추정했다.",
          "task": "중복 발송 로그를 통해 실제 오류 원인을 좁혀야 했다.",
          "action": "시간순으로 모은 로그에서 초기 추정과 맞지 않는 단서를 찾고, 그 단서가 두 서버의 스케줄러 동시 실행을 가리킨다고 해석한 이유를 설명한다.",
          "result": "클라이언트 문제라는 추정을 바꾸고 스케줄러 중복 실행을 원인으로 판단할 수 있었던 논리적 연결이 드러난다."
        },
        "expectedEvidence": [
          "클라이언트 문제라는 초기 추정을 바꾸게 한 결정적 로그 단서",
          "해당 단서가 초기 추정으로는 설명되지 않는 이유",
          "해당 단서가 두 서버의 스케줄러 동시 실행을 가리키는 이유"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송 로그를 시간순으로 모으셨네요. 처음의 클라이언트 문제 추정을 바꾸게 한 결정적 단서를 들려주세요.",
      "answerTip": "처음 생각과 단서를 본 뒤의 생각을 대비해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "초기 추정을 바꾸게 한 결정적 로그 단서가 구체적으로 드러난다.",
            "그 단서가 클라이언트 문제라는 추정과 맞지 않는 이유를 설명한다.",
            "단서와 두 서버의 스케줄러 동시 실행을 연결해 원인을 좁힌 판단을 입증한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "초기 추정을 바꾼 로그 단서는 드러나지만 구체적인 설명이 부족하다.",
            "스케줄러 중복 실행과의 관련성은 설명하지만 초기 추정을 배제한 이유는 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "초기 추정을 바꾸게 한 결정적 단서가 드러나지 않는다.",
            "로그를 봤다는 말이나 최종 원인만 제시하고 둘 사이의 연결을 설명하지 못한다.",
            "잠금 적용이나 체크리스트 추가만 설명해 로그로 원인을 좁힌 판단을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청의 목적을 바탕으로 구현 범위를 구체화하는 역량을 검증한다. 개발 담당 팀원과 조정한 요구사항의 구현 범위를 정한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰를 바탕으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정한 상황",
          "task": "사용자 요청 중 서비스에서 구현할 범위의 경계를 정하는 일",
          "action": "요청의 목적과 구현상 제약을 비교하여 구현 범위를 정한 기준을 실제 요구사항에 연결해 설명",
          "result": "그 기준에 따라 구현 범위가 어떻게 구분되었는지 드러나며, 범위 결정이 요청의 목적과 연결됨"
        },
        "expectedEvidence": [
          "구현할 요구사항의 범위를 정한 구체적인 판단 기준",
          "해당 기준의 바탕이 된 사용자 요청의 목적이나 구현상 제약",
          "기준을 실제 요구사항에 적용하여 정한 범위의 경계"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 요구사항 정의서를 작성하셨네요. 개발 담당 팀원과 조정한 구현 범위는 어떤 기준으로 정하셨나요?",
      "answerTip": "조정 전후의 범위를 대비해 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 기준을 명확히 설명하고 실제 요구사항에 적용한 판단을 제시한다.",
            "사용자 요청의 목적이나 구현상 제약이 그 기준으로 이어진 이유를 구체적으로 설명한다.",
            "구현 범위의 경계가 분명하며, 제시한 기준과 일관된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 기준은 제시하지만 실제 요구사항에 적용한 설명이 제한적이다.",
            "사용자 요청의 목적이나 구현상 제약을 언급하지만 기준과의 연결이 충분하지 않다.",
            "정해진 구현 범위는 알 수 있으나 경계가 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 기준을 밝히지 않거나 요구사항 목록만 나열한다.",
            "범위 결정의 이유가 사용자 요청의 목적이나 구현상 제약과 연결되지 않는다.",
            "실제 어떤 범위로 정했는지 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서도 구현 가능한 수준으로 화면의 상태를 설계하는 역량을 검증한다. 화면설계서에 담은 예외 상황 중 가장 고민했던 상황의 화면 상태를 정한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스의 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성한 경험",
          "task": "선택한 예외 상황에서 화면이 어떤 상태로 나타나야 하는지 정하는 일",
          "action": "예외가 발생하는 조건과 사용자에게 필요한 화면 반응을 연결하여 화면 상태를 선택한 이유를 설명",
          "result": "선택한 화면 상태가 해당 예외 상황을 어떻게 처리하는지 드러나고, 구현할 동작을 해석할 수 있음"
        },
        "expectedEvidence": [
          "가장 고민했던 예외 상황의 화면 상태를 정한 구체적인 이유",
          "그 판단의 바탕이 된 예외 발생 조건과 사용자 흐름",
          "선택한 화면 상태가 해당 조건에서 어떻게 동작하는지에 대한 설명"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장에 예외 상황을 담으셨네요. 가장 고민했던 예외 상황의 화면 상태를 정한 이유를 들려주세요.",
      "answerTip": "당시 떠올린 화면 모습을 먼저 짚어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 예외 상황의 화면 상태를 정한 이유가 구체적이며 설계 판단이 명확하다.",
            "예외 발생 조건과 사용자 흐름을 연결하여 해당 화면 상태가 필요한 이유를 설명한다.",
            "선택한 상태에서 화면이 어떻게 동작하는지 구현 가능한 수준으로 설명하며 판단 이유와 일치한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 상태를 정한 이유는 제시하지만 해당 예외 상황에 특화된 설명이 부족하다.",
            "예외 발생 조건이나 사용자 흐름은 드러나지만 화면 상태와의 연결이 부분적이다.",
            "화면의 동작을 대략 설명하지만 일부 해석이 필요한 부분이 남는다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 상태를 정한 이유 없이 화면 구성이나 예외 상황의 이름만 나열한다.",
            "예외 발생 조건과 선택한 화면 상태 사이의 관계를 설명하지 못한다.",
            "선택한 화면 상태에서 어떤 동작이 일어나는지 파악하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 확인할 수 있는지 검증한다. 평소 용량의 두 배로 입력된 진통제 처방에서 투약을 멈추기로 한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황이다.",
          "task": "해당 처방을 그대로 수행해도 되는지 판단해야 했다.",
          "action": "처방 용량의 차이를 이상 신호로 받아들인 이유와, 확인 전에는 투약을 진행할 수 없다고 판단한 내용을 설명한다.",
          "result": "투약을 보류하고 담당의에게 확인한 결과 입력 오류로 밝혀졌다는 사실이 당시 판단과 연결된다."
        },
        "expectedEvidence": [
          "처방을 그대로 수행하지 않고 투약을 멈추기로 한 판단",
          "평소 용량과의 차이를 확인이 필요한 이상 신호로 본 이유",
          "담당의 확인으로 밝혀진 입력 오류와 당시 판단의 연결"
        ]
      },
      "question": "수술 후 환자의 진통제 처방이 평소 용량의 두 배로 들어온 경험을 적으셨네요. 투약을 그대로 진행하지 않기로 한 판단을 들려주세요.",
      "answerTip": "당시 알던 사실과 확인 뒤 알게 된 사실을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "의심스러운 처방을 확인하기 전에는 투약을 진행하지 않겠다는 판단이 명확하다.",
            "평소 용량과의 차이가 왜 처방 확인을 요구하는 신호였는지 당시 알고 있던 사실에 연결해 설명한다.",
            "담당의 확인 결과 입력 오류였다는 사실을 제시하며 투약 보류 판단과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 이상해 투약을 멈췄다는 판단은 드러난다.",
            "평소 용량과 달랐다는 사실은 제시하지만, 확인 없이 진행할 수 없다고 본 이유는 충분히 설명하지 못한다.",
            "담당의에게 확인했다는 사실은 언급하지만 확인 결과와 판단의 연결이 짧거나 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추기로 한 본인의 판단이 드러나지 않거나 일반적인 투약 원칙만 설명한다.",
            "처방에서 무엇을 의심했는지 설명하지 못하거나 확인되지 않은 처방을 그대로 수행해도 된다고 답한다.",
            "담당의에게 확인한 사실과 입력 오류라는 결과를 당시 판단에 연결하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
